+    private boolean shouldCarryTradeCount(final Num volumeRemainder) {
+        if (carryOverPolicy != RemainderCarryOverPolicy.PROPORTIONAL_WITH_TRADE_COUNT) {
+            return false;
+        }
+        if (lastTradeVolume == null || lastTradeVolume.isZero()) {
